function ListFactors(context) {
  let component_state = {
    action: 'return_to_website',
    selected_factor: null,
    enrollment_id: null,
  }

  const factorsMeta = {
    sms: {
      title: "Phone Message",
      description:
        "Users will receive a phone message with a verification code",
    },
    "push-notification": {
      title: "Push Notification using Auth0 Guardian",
      description: "Provide a push notification using Auth0 Guardian.",
    },
    otp: {
      title: "One-time Password",
      description:
        "Provide a one-time password using Google Authenticator or similar.",
    },
    email: {
      title: "Email",
      description:
        "Users will receive an email message containing a verification code.",
    },
    duo: {
      title: "Duo Security",
      description: "Use your DUO account for Multi-factor Authentication.",
    },
    "webauthn-roaming": {
      title: "WebAuthn with FIDO Security Keys",
      description:
        "Depending on your browser, you can use WebAuthn-compliant security keys (like FIDO2) as a second factor of authentication.",
    },
    "webauthn-platform": {
      title: "WebAuthn with FIDO Device Biometrics",
      description:
        "Depending on your browser, you can use WebAuthn-compliant device biometrics as a second factor of authentication",
    },
    "recovery-code": {
      title: "Recovery Code",
      description:
        "Provide a unique code that allows users to regain access to their account.",
    },
  };

  function filterFactors(availableFactors, enrolledFactors, allowedFactors) {
    return availableFactors
      .filter(
        (factor) => factor.enabled && allowedFactors.includes(factor.name)
      )
      .map((factor) => {
        const enrollmentInfo = enrolledFactors.find((enrollment) => {
          let factorName = factor.name;

          if (factor.name === "sms" || factor.name === "voice") {
            factorName = "phone";
          }

          return enrollment.type.includes(factorName);
        });

        return {
          ...factor,
          enrollment_id: enrollmentInfo?.id,
        };
      });
  }

  function handleEnroll(factor) {
    component_state.action = 'enroll_factor';
    component_state.selected_factor = factor.name;
    context.form.goForward();
  }

  function handleRemove(factor) {
    component_state.action = 'remove_factor';
    component_state.selected_factor = factor.name;
    component_state.enrollment_id = factor.enrollment_id;
    context.form.goForward();
  }

  function buildFactorOption(factor) {
    const factorContainer = document.createElement('div');
    factorContainer.classList.add('factor-container');

    const factorInfo = document.createElement('div');
    factorInfo.classList.add('factor-info-container');

    const factorTitleContainer = document.createElement('div');
    factorTitleContainer.classList.add('factor-title-container');

    const factorTitle = document.createElement('span');
    factorTitle.classList.add('factor-title');
    factorTitle.innerText = factorsMeta[factor.name].title;

    factorTitleContainer.appendChild(factorTitle);

    if (factor.enrollment_id) {
      const factorTitleTag = document.createElement('span');
      factorTitleTag.classList.add('factor-tag');
      factorTitleTag.innerText = 'Enrolled';

      factorTitleContainer.appendChild(factorTitleTag);
    }

    const factorDescription = document.createElement('div');
    factorDescription.classList.add('factor-description');
    factorDescription.innerText = factorsMeta[factor.name].description;

    factorInfo.appendChild(factorTitleContainer);
    factorInfo.appendChild(factorDescription);

    factorContainer.appendChild(factorInfo);

    const factorAction = document.createElement('div');
    factorAction.classList.add('factor-action');

    const factorButton = document.createElement('button');
    factorButton.type = 'button';
    factorAction.appendChild(factorButton);

    if (factor.enrollment_id) {
      factorButton.classList.add('factor-remove');
      factorButton.innerText = 'Remove';
      factorButton.onclick = () => handleRemove(factor);
    } else {
      factorButton.classList.add('factor-enroll');
      factorButton.innerText = 'Enroll';
      factorButton.onclick = () => handleEnroll(factor);
    }

    factorContainer.appendChild(factorAction);

    return factorContainer;
  }

  function mountComponent() {
    const config = context.custom.getParams();
    const { available_factors, enrolled_factors, allowed_factors } = config;

    const filteredFactors = filterFactors(available_factors, enrolled_factors, allowed_factors);

    const factorsContainer = document.createElement('div');
    factorsContainer.classList.add('factors-container');

    filteredFactors.forEach((factor) => {
      const factorOption = buildFactorOption(factor);
      factorsContainer.appendChild(factorOption);
    });

    return factorsContainer;
  }

  return {
    init() {
      return mountComponent();
    },

    getValue() {
      return component_state;
    },
  };
}

style.css:
.factors-container {
  display: flex;
  flex-direction: column;
}

.factor-container:not(:last-child) {
  border-bottom: 1px solid var(--input-border-color);
  padding-bottom: var(--spacing-3);
  margin-bottom: var(--spacing-3);
}

.factor-description {
  font-size: var(--font-size-small);
  color: var(--font-light-color);
}

.factor-tag {
  background: var(--success-color);
  padding: var(--spacing-0-5) var(--spacing-1);
  color: white;
  margin-left: var(--spacing-1);
  font-size: var(--font-size-small);
  border-radius: var(--border-radius);
}

.waiting-icon {
  display: flex;
  justify-content: center;
  margin-bottom: var(--spacing-2);
}

.waiting-icon svg {
  height: 48px;
  width: 48px;
  stroke: var(--font-light-color);
}

.waiting-container {
  text-align: center;
}

.waiting-title {
  color: var(--font-light-color);
}

.factor-action {
  margin: var(--spacing-1) 0;
}
.factor-action button {
  border-radius: var(--border-radius);
  padding: var(--spacing-0-5) var(--spacing-3);
  font-size: var(--font-size-small);
  border: 1px solid transparent;
  cursor: pointer;
}

button.factor-enroll {
  background: rgb(17, 17, 17);
  color: hsl(210 40% 98%);
  border-color: rgb(17, 17, 17);
}

button.factor-remove {
  background: #fff;
  color: rgb(17, 17, 17);
  border-color: var(--input-border-color);
}
